void mainImage( out vec4 o, vec2 u )
{  
    float t = .4*iTime, i, j, k;
    o.xyz = iResolution;
    u = (u+u-o.xy)/o.y + .15*t;   
    vec4 c;
    for (o -= o; i++ < 13.; c += o = sqrt(o*o+.005)) 
        u = 1.3*u*mat2(cos(i*i + vec4(8,19,41,8))) + i - .1*i*t,
        u += .03* exp(cos(t*i+i*i+o.x*4.-4.*u.yx)),
        j = 6.5-i,
        k = cos(u.y/j+u.x/i + t)*sin(u.x/i-u.y/j),
        o += pow(k*k, 1.+i+i*cos(i*i+t*i*.4+dot(o+cos(u.y),o-cos(u.x)))) 
            * step(.6*k,o.x) * (1.+cos(vec4(0,1,2,0)+i)),//vec4(.8,1,1.2,0),
        o = mix(o, length(o)-o.bgra, .2*cos(i*9.*t+i/max(1.,mod(t+.3*i,4.))));
    //  ^^ set o=o; to remove flashing
    o += .2*c;    
    o = .9-exp(-.4*sqrt(o*o*o));
    o += .2*o*o;  
    o.bg*= tanh(o.r*1.6);
    o += .06*sin(8.*u.x);    
}
